          g("Complete o somatório de todos os valores de uma lista numérica usando reduce com zero como ponto de partida:", ["numeros.reduce((acc, x) => acc + x, 0)"], "O acumulador soma progressivamente cada número a partir de 0.", "const total = ____;"),
          o("Ordene a mecânica do acumulador na soma de [10, 20, 30] com valor inicial 0 em .reduce():", ["Iteração 1: acumulador vale 0; soma com 10; retorna novo acumulador = 10","Iteração 2: acumulador vale 10; soma com 20; retorna novo acumulador = 30","Iteração 3: acumulador vale 30; soma com 30; retorna novo acumulador = 60","Fim da coleção: devolve o valor consolidado final 60 para quem chamou"], "Linha de acumulação passo a passo na execução de uma função redutora."),
          p("Associe o papel no reduce à sua definição operacional:", [["Acumulador (acc)","Valor retornado pela iteração anterior que carrega o estado progressivo"],["Item atual (cur)","Elemento do array inspecionado no ciclo corrente de iteração"],["Valor inicial (init)","Ponto de partida fornecido como segundo argumento do reduce"],["Função redutora (reducer)","Regra de negócio pura que combina acumulador e item atual"]], "Terminologia e componentes da mecânica de redução em JavaScript.")
